import { BMSGeneratedRegisterCatalog } from '../generated/BMSGeneratedRegisterCatalog';
import { BmsBleTransport } from './bleTransport';
import { BatteryStatusSnapshot,BmsProtocolError,asciiStringFromWords,decodeBatteryStatus,echo,encodeAsciiWords,macStringFromWords,parseResponse,readHolding,writeMultiple,writeSingle } from './protocol';
export interface DeviceIdentitySnapshot{macAddress:string;serialNumber:string;hardwareVersion:string;softwareVersion:string;}
export interface RegisterBlock{start:number;words:number[];}
export class BmsService{
  constructor(private readonly transport:BmsBleTransport){}
  async echoTest():Promise<void>{const request=echo(new Uint8Array([0x12,0x34,0x56,0x78]));const response=parseResponse(await this.transport.request(request,request.length));if(response.kind!=='echo')throw new BmsProtocolError('Echo 响应类型错误');}
  async refreshIdentity():Promise<DeviceIdentitySnapshot>{const mac=await this.readBlock(BMSGeneratedRegisterCatalog.MAC_ADDRESS_START,BMSGeneratedRegisterCatalog.MAC_ADDRESS_WORD_COUNT);const serial=await this.readBlock(BMSGeneratedRegisterCatalog.PRODUCT_SERIAL_START,BMSGeneratedRegisterCatalog.PRODUCT_SERIAL_WORD_COUNT);const hardware=await this.readBlock(BMSGeneratedRegisterCatalog.PRODUCT_HARDWARE_VERSION_START,BMSGeneratedRegisterCatalog.PRODUCT_HARDWARE_VERSION_WORD_COUNT);const software=await this.readBlock(BMSGeneratedRegisterCatalog.PRODUCT_SOFTWARE_VERSION_START,BMSGeneratedRegisterCatalog.PRODUCT_SOFTWARE_VERSION_WORD_COUNT);return{macAddress:macStringFromWords(mac.words),serialNumber:asciiStringFromWords(serial.words),hardwareVersion:asciiStringFromWords(hardware.words),softwareVersion:asciiStringFromWords(software.words)};}
  async refreshBatteryStatus():Promise<BatteryStatusSnapshot>{const legacy=await this.readBlock(BMSGeneratedRegisterCatalog.LEGACY_CELL_ARRAY_START,BMSGeneratedRegisterCatalog.LEGACY_CELL_ARRAY_WORD_COUNT);const system=await this.readBlock(BMSGeneratedRegisterCatalog.SYSTEM_STATUS_START,BMSGeneratedRegisterCatalog.SYSTEM_STATUS_WORD_COUNT);const realtime=await this.readBlock(BMSGeneratedRegisterCatalog.REALTIME_STATUS_START,BMSGeneratedRegisterCatalog.REALTIME_STATUS_WORD_COUNT);return decodeBatteryStatus(realtime.words,legacy.words,system.words);}
  async readProtectPreview():Promise<RegisterBlock>{return this.readBlock(BMSGeneratedRegisterCatalog.PROTECT_PREVIEW_START,BMSGeneratedRegisterCatalog.PROTECT_PREVIEW_WORD_COUNT);}
  async readEventLogPreview():Promise<RegisterBlock>{return this.readBlock(BMSGeneratedRegisterCatalog.EVENT_LOG_PREVIEW_START,BMSGeneratedRegisterCatalog.EVENT_LOG_PREVIEW_WORD_COUNT);}
  async writeSoc(value:number):Promise<void>{if(!Number.isInteger(value)||value<0||value>100)throw new BmsProtocolError('SOC 必须为 0~100 的整数');const response=parseResponse(await this.transport.request(writeSingle(BMSGeneratedRegisterCatalog.SOC_WRITE_REGISTER_START,value)));if(response.kind!=='write_single_ack')throw new BmsProtocolError('SOC 写入响应类型错误');}
  async writeBluetoothNameSuffix(suffix:string):Promise<void>{const cleaned=suffix.trim();if(!cleaned)throw new BmsProtocolError('蓝牙名后缀不能为空');if(!/^[A-Za-z0-9_-]+$/.test(cleaned))throw new BmsProtocolError('蓝牙名后缀仅允许 A-Z a-z 0-9 _ -');if(cleaned.length>10)throw new BmsProtocolError('当前 BLE 单包限制下，蓝牙名后缀最多写 10 个 ASCII 字节');const values=encodeAsciiWords(cleaned);const response=parseResponse(await this.transport.request(writeMultiple(BMSGeneratedRegisterCatalog.BT_NAME_START,values)));if(response.kind!=='write_multiple_ack')throw new BmsProtocolError('蓝牙名写入响应类型错误');}
  async readBlock(start:number,quantity:number):Promise<RegisterBlock>{const response=parseResponse(await this.transport.request(readHolding(start,quantity)));if(response.kind==='exception')throw new BmsProtocolError(`Modbus Exception func=0x${response.function.toString(16)} code=0x${response.code.toString(16)}`);if(response.kind!=='read_holding')throw new BmsProtocolError('读取寄存器响应类型错误');return{start,words:response.words};}
}
